<?php $page=max(1,min(100000,(int)($_GET['page']??1)));$offset=($page-1)*100;$events=all('SELECT * FROM audit_events ORDER BY id DESC LIMIT 101 OFFSET '.$offset);$more=count($events)>100;$events=array_slice($events,0,100); ?>
<div class="workflow-heading"><a href="/admin">← Administration</a><h1>Site audit ledger</h1><p>Private operational history · UTC timestamps · append-only</p></div>
<?php foreach($events as $event): ?><article class="ledger-entry"><time><?=e($event['created_at'])?> UTC</time><h2><?=e($event['action'])?> · <?=e($event['new_state'])?></h2><p><?=e($event['reason'])?></p><p class="fine"><?=e($event['actor_name'])?> · <?=e($event['actor_type'])?> · <?=e($event['entity_type'])?> <?=e($event['entity_id'])?></p><?php if($event['research_id']): ?><a href="/admin/research/<?=e($event['research_id'])?>/ledger">Project audit trail</a><?php endif ?><?php if($event['metadata']!=='[]'): ?><details><summary>How / details</summary><pre><?=e(json_encode(json_decode($event['metadata'],true),JSON_PRETTY_PRINT))?></pre></details><?php endif ?></article><?php endforeach ?>
<nav class="pagination"><?php if($page>1): ?><a href="?page=<?=$page-1?>">Newer updates</a><?php endif ?><?php if($more): ?><a href="?page=<?=$page+1?>">Older updates</a><?php endif ?></nav>
